// @ts-ignore
import * as codec from "../codec/mod.js";
// @ts-ignore
import * as util from "../util.js";
// @ts-ignore
import * as session from "./mod.js";
export const minPacketLength = 9;
export const maxPacketLength = Number.MAX_VALUE;
export class Session {
    constructor(conn) {
        Object.defineProperty(this, "conn", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "channels", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "incoming", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "enc", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "dec", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "done", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "closed", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this.conn = conn;
        this.enc = new codec.Encoder(conn);
        this.dec = new codec.Decoder(conn);
        this.channels = [];
        this.incoming = new util.queue();
        this.done = this.loop();
        this.closed = false;
    }
    async open() {
        const ch = this.newChannel();
        ch.maxIncomingPayload = session.channelMaxPacket;
        await this.enc.encode({
            ID: codec.OpenID,
            windowSize: ch.myWindow,
            maxPacketSize: ch.maxIncomingPayload,
            senderID: ch.localId
        });
        if (await ch.ready.shift()) {
            return ch;
        }
        throw "failed to open";
    }
    accept() {
        return this.incoming.shift();
    }
    async close() {
        for (const ids of Object.keys(this.channels)) {
            const id = parseInt(ids);
            if (this.channels[id] !== undefined) {
                this.channels[id].shutdown();
            }
        }
        this.conn.close();
        this.closed = true;
        await this.done;
    }
    async loop() {
        try {
            while (true) {
                const msg = await this.dec.decode();
                if (msg === null) {
                    this.close();
                    return;
                }
                if (msg.ID === codec.OpenID) {
                    await this.handleOpen(msg);
                    continue;
                }
                const cmsg = msg;
                const ch = this.getCh(cmsg.channelID);
                if (ch === undefined) {
                    if (this.closed) {
                        return;
                    }
                    console.warn(`invalid channel (${cmsg.channelID}) on op ${cmsg.ID}`);
                    continue;
                }
                await ch.handle(cmsg);
            }
        }
        catch (e) {
            if (e.message && e.message.contains && e.message.contains("Connection reset by peer")) {
                return;
            }
            throw e;
        }
    }
    async handleOpen(msg) {
        if (msg.maxPacketSize < minPacketLength || msg.maxPacketSize > maxPacketLength) {
            await this.enc.encode({
                ID: codec.OpenFailureID,
                channelID: msg.senderID
            });
            return;
        }
        const c = this.newChannel();
        c.remoteId = msg.senderID;
        c.maxRemotePayload = msg.maxPacketSize;
        c.remoteWin = msg.windowSize;
        c.maxIncomingPayload = session.channelMaxPacket;
        this.incoming.push(c);
        await this.enc.encode({
            ID: codec.OpenConfirmID,
            channelID: c.remoteId,
            senderID: c.localId,
            windowSize: c.myWindow,
            maxPacketSize: c.maxIncomingPayload
        });
    }
    newChannel() {
        const ch = new session.Channel(this);
        ch.remoteWin = 0;
        ch.myWindow = session.channelWindowSize;
        ch.localId = this.addCh(ch);
        return ch;
    }
    getCh(id) {
        const ch = this.channels[id];
        if (ch && ch.localId !== id) {
            console.log("bad ids:", id, ch.localId, ch.remoteId);
        }
        return ch;
    }
    addCh(ch) {
        this.channels.forEach((v, i) => {
            if (v === undefined) {
                this.channels[i] = ch;
                return i;
            }
        });
        this.channels.push(ch);
        return this.channels.length - 1;
    }
    rmCh(id) {
        delete this.channels[id];
    }
}
